                .andExpect(status().isOk());
        createJoint(SUBJECT_A, "jc-1", SUBJECT_A, SUBJECT_B, 1, 1, "joint-1", "payload-v1")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.version").value(1));
